pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // An attacker that will reenter c.initialize during the minting/safeTransfer flow by having
    // its onERC721Received call invoke a view on c to observe feeRate and initialized state.
    // It stores the observed feeRate during reentrancy so the test can assert on it after initialize.
    ReentrantObserver attacker;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
        attacker = new ReentrantObserver(address(c));
    }

    // fuzz parameters: _feeRate and a boolean that chooses whether baseToken==address(0) path (affects payable behavior)
    function testFuzz_property(uint16 _feeRate, bool useEthPath) public {
        // keep feeRate domain wide but within contract check; feeRate must be <= 5000 to be admissible
        vm.assume(_feeRate <= 5000);

        // choose baseToken as address(0) or not via useEthPath
        address baseToken = useEthPath ? address(0) : address(1); // address(1) is a dummy ERC20 address

        // Prepare parameters to call initialize. We will supply the attacker as the nft address so that
        // during any safeTransferFrom to/from nft the attacker contract's onERC721Received is invoked.
        address nft = address(attacker);
        uint128 vBase = 1;
        uint128 vNft = 1;
        uint56 changeFee = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        // Reset the attacker observed values before the call
        attacker.reset();

        // Now perform initialize. The attacker will attempt to reenter (via onERC721Received) and read feeRate()
        // The universal property: after initialize() returns successfully, c.feeRate() == _feeRate.
        // We call as this test contract (owner/setup) — attacker will be triggered by any safeTransferFrom inside initialize's flow
        // In the real contract initialize does not perform transfers, but the mutant reordering makes initialized=true earlier
        // and the attacker uses a reentrant hook triggered by being used as the nft address to probe state during initialization.

        // We simply call initialize; depending on mutant/reference behavior, attacker.observedDuringReentry() may record a differing feeRate.
        bool ok;
        try c.initialize(
            baseToken,
            nft,
            vBase,
            vNft,
            changeFee,
            _feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if initialization succeeded (ok==true) then after return c.feeRate() equals the provided _feeRate.
        // This is the universal property the reference satisfies; the mutant can be distinguished because the attacker may have
        // observed a different feeRate during reentrancy (but we assert the post-call getter value equals the argument).
        assertTrue(!ok || c.feeRate() == _feeRate);
    }
}

// Minimal helper that attempts to observe c's state during reentrancy.
contract ReentrantObserver {
    C target;
    uint256 public observedFeeRate;
    bool public observedInitialized;

    constructor(address _target) {
        target = C(_target);
    }

    function reset() external {
        observedFeeRate = type(uint256).max;
        observedInitialized = false;
    }

    // Implement ERC721 token receiver hook; when invoked, reenter target and read feeRate and initialized.
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        // try to read and record values from target during reentrancy
        // These calls are view getters and will not revert; record them
        observedFeeRate = target.feeRate();
        observedInitialized = target.initialized();
        return ReentrantObserver.onERC721Received.selector;
    }

    // Expose selector
    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return ReentrantObserver.onERC721Received.selector;
    }
}
